(()=>{'use strict';const form=document.getElementById('diagnostic-form');if(!form)return;const sections=[...form.querySelectorAll('[data-step]')],buttons=[...document.querySelectorAll('[data-goto]')],$=id=>document.getElementById(id);let step=0,current=null,summary='';
function show(index,focus=false){step=index;sections.forEach((s,i)=>s.hidden=i!==step);buttons.forEach((b,i)=>{if(i===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('brief-prev').disabled=step===0;$('brief-next').hidden=step===3;$('step-indicator').textContent=`Etapa ${step+1} de 4`;if(focus)sections[step].querySelector('h2').focus();}
function validateStep(){const invalid=sections[step].querySelector(':invalid');if(invalid){invalid.reportValidity();return false;}return true;}
buttons.forEach(b=>b.addEventListener('click',()=>{if(validateStep())show(Number(b.dataset.goto),true);}));$('brief-prev').addEventListener('click',()=>show(Math.max(0,step-1),true));$('brief-next').addEventListener('click',()=>{if(validateStep())show(Math.min(3,step+1),true);});
const fields={empresa:'Negócio',setor:'Setor',atividade_publico:'Atividade e público',site_atual:'Site atual',dificuldades:'Dificuldades',objetivo_prioritario:'Mudança prioritária',modelo_preferido:'Modelo de referência',direcao_visual:'Direção visual',cor_principal:'Cor principal',cor_fundo:'Cor de fundo',cor_detalhe:'Cor de detalhe',nao_gosta:'O que evitar',referencias:'Referências e motivos',materiais_marca:'Materiais existentes',recursos:'Recursos desejados',pessoas_equipe:'Pessoas na gestão',quantidade_itens:'Quantidade de itens',canais_atuais:'Canais atuais',regras_operacao:'Regras da operação',sistemas_integracoes:'Sistemas e integrações',responsavel_atualizacoes:'Atualizações da base',faixa_investimento:'Investimento a avaliar',situacao_contas:'Situação das contas',prazo_prioridades:'Datas e prioridades',responsavel:'Responsável',email_retorno:'E-mail de retorno',observacoes:'Outras observações'};
function download(name,value,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([value],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
form.addEventListener('submit',e=>{e.preventDefault();for(let i=0;i<sections.length;i++){const invalid=sections[i].querySelector(':invalid');if(invalid){show(i);invalid.reportValidity();return;}}const data=new FormData(form),answers={};for(const key of Object.keys(fields)){const values=data.getAll(key).map(v=>String(v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').trim()).filter(Boolean);answers[key]=['dificuldades','recursos'].includes(key)?values:values[0]||'';}current={version:1,type:'relax-studios-diagnostico-digital',preparedAt:new Date().toISOString(),automaticSend:false,answers};summary='DIAGNÓSTICO DIGITAL / RELAX STUDIOS\n\n'+Object.entries(fields).map(([key,label])=>{const value=answers[key];return label+': '+(Array.isArray(value)?value.join('; ')||'A definir':value||'A definir');}).join('\n\n')+'\n\nPreparado na página; sem envio automático. Domínio e contas serão definidos sob titularidade do cliente.';$('brief-preview').value=summary;$('brief-result').hidden=false;$('brief-result-title').focus();$('brief-result-status').textContent='Revise antes de copiar, baixar ou compartilhar.';
 ['copy-brief','download-brief','download-brief-json'].forEach(id=>$(id).disabled=false);
 const config=window.RELAX_CONFIG||{};if(config.emailActive&&config.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email)){const a=$('mail-brief');a.href='mailto:'+config.email+'?subject='+encodeURIComponent('Diagnóstico digital · '+(answers.empresa||'Novo projeto'))+'&body='+encodeURIComponent('Olá, preparei meu diagnóstico digital na página da Relax Studios. Vou anexar ou colar o resumo gerado antes de enviar.');a.hidden=false;}
});
form.addEventListener('input',()=>{if(current){$('brief-result-status').textContent='Há alterações nas respostas. Prepare o diagnóstico novamente antes de compartilhar.';$('copy-brief').disabled=true;$('download-brief').disabled=true;$('download-brief-json').disabled=true;$('mail-brief').hidden=true;}});
$('copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summary);$('brief-result-status').textContent='Resumo copiado. Nenhuma mensagem foi enviada.';}catch{$('brief-preview').focus();$('brief-preview').select();$('brief-result-status').textContent='Selecione e copie o resumo pelo seu dispositivo.';}});$('download-brief').addEventListener('click',()=>download('diagnostico-relax-studios.txt',summary,'text/plain;charset=utf-8'));$('download-brief-json').addEventListener('click',()=>download('diagnostico-relax-studios.json',JSON.stringify(current,null,2),'application/json'));show(0);
})();
